// AdminServiceHandler is an implementation of the vca.admin.v1.AdminService service.
type AdminServiceHandler interface {
	// CreateTenant creates one tenant. A tenant is one operator organisation.
	CreateTenant(context.Context, *connect.Request[v1.CreateTenantRequest]) (*connect.Response[v1.CreateTenantResponse], error)
	// GetTenant returns one tenant by id.
	GetTenant(context.Context, *connect.Request[v1.GetTenantRequest]) (*connect.Response[v1.GetTenantResponse], error)
	// ListTenants returns tenants in pages.
	ListTenants(context.Context, *connect.Request[v1.ListTenantsRequest]) (*connect.Response[v1.ListTenantsResponse], error)
	// UpdateTenant changes the display name or the state of one tenant.
	UpdateTenant(context.Context, *connect.Request[v1.UpdateTenantRequest]) (*connect.Response[v1.UpdateTenantResponse], error)
	// DeleteTenant removes one tenant and every record it owns.
	DeleteTenant(context.Context, *connect.Request[v1.DeleteTenantRequest]) (*connect.Response[v1.DeleteTenantResponse], error)
	// UpsertTrustEntry creates or replaces one trust entry (ADR-011).
	// The admin service forwards the entry to the trust service, which
	// publishes it in every enabled method.
	UpsertTrustEntry(context.Context, *connect.Request[v1.UpsertTrustEntryRequest]) (*connect.Response[v1.UpsertTrustEntryResponse], error)
	// GetTrustEntry returns one trust entry by entity identifier.
	GetTrustEntry(context.Context, *connect.Request[v1.GetTrustEntryRequest]) (*connect.Response[v1.GetTrustEntryResponse], error)
	// ListTrustEntries returns trust entries in pages.
	ListTrustEntries(context.Context, *connect.Request[v1.ListTrustEntriesRequest]) (*connect.Response[v1.ListTrustEntriesResponse], error)
	// DeleteTrustEntry removes one trust entry.
	DeleteTrustEntry(context.Context, *connect.Request[v1.DeleteTrustEntryRequest]) (*connect.Response[v1.DeleteTrustEntryResponse], error)
	// ApproveTrustEntry sets a pending trust entry to active, so relying
	// parties trust the entity. The audit log records the decision.
	ApproveTrustEntry(context.Context, *connect.Request[v1.ApproveTrustEntryRequest]) (*connect.Response[v1.ApproveTrustEntryResponse], error)
	// RejectTrustEntry removes a pending trust entry. The audit log
	// records the decision.
	RejectTrustEntry(context.Context, *connect.Request[v1.RejectTrustEntryRequest]) (*connect.Response[v1.RejectTrustEntryResponse], error)
	// CreateAuthProvider registers one OIDC provider (ADR-012 decision 5).
	// The service fetches the discovery document to check the URL.
	CreateAuthProvider(context.Context, *connect.Request[v1.CreateAuthProviderRequest]) (*connect.Response[v1.CreateAuthProviderResponse], error)
	// GetAuthProvider returns one provider by id.
	GetAuthProvider(context.Context, *connect.Request[v1.GetAuthProviderRequest]) (*connect.Response[v1.GetAuthProviderResponse], error)
	// ListAuthProviders returns providers in pages.
	ListAuthProviders(context.Context, *connect.Request[v1.ListAuthProvidersRequest]) (*connect.Response[v1.ListAuthProvidersResponse], error)
	// UpdateAuthProvider changes one provider.
	UpdateAuthProvider(context.Context, *connect.Request[v1.UpdateAuthProviderRequest]) (*connect.Response[v1.UpdateAuthProviderResponse], error)
	// DeleteAuthProvider removes one provider. Active sessions end.
	DeleteAuthProvider(context.Context, *connect.Request[v1.DeleteAuthProviderRequest]) (*connect.Response[v1.DeleteAuthProviderResponse], error)
	// OnboardProvider registers one OIDC provider from its issuer URL.
	// The service reads the provider metadata and registers a client. It
	// runs the same onboarding path as CreateAuthProvider
	// (ADR-010 decision 3).
	OnboardProvider(context.Context, *connect.Request[v1.OnboardProviderRequest]) (*connect.Response[v1.OnboardProviderResponse], error)
	// CreateApiKey creates one machine API key. The response shows the
	// secret value once. The service stores only its hash.
	CreateApiKey(context.Context, *connect.Request[v1.CreateApiKeyRequest]) (*connect.Response[v1.CreateApiKeyResponse], error)
	// ListApiKeys returns API keys without their secret values.
	ListApiKeys(context.Context, *connect.Request[v1.ListApiKeysRequest]) (*connect.Response[v1.ListApiKeysResponse], error)
	// RevokeApiKey disables one API key at once.
	RevokeApiKey(context.Context, *connect.Request[v1.RevokeApiKeyRequest]) (*connect.Response[v1.RevokeApiKeyResponse], error)
	// GetServiceHealth returns the health of every service in the deployment.
	GetServiceHealth(context.Context, *connect.Request[v1.GetServiceHealthRequest]) (*connect.Response[v1.GetServiceHealthResponse], error)
	// QueryAuditLog returns audit records that match a filter, newest first.
	QueryAuditLog(context.Context, *connect.Request[v1.QueryAuditLogRequest]) (*connect.Response[v1.QueryAuditLogResponse], error)
	// OnboardAdmin binds the first super admin (ADR-010 decision 4).
	// The caller sends the one time bootstrap token and an OIDC id token.
	// The service binds the iss and sub claims to the super admin role.
	OnboardAdmin(context.Context, *connect.Request[v1.OnboardAdminRequest]) (*connect.Response[v1.OnboardAdminResponse], error)
	// ListCommands returns the command tree with descriptions.
	// The CLI, the man pages, and the portal help page render this list.
	ListCommands(context.Context, *connect.Request[v1.ListCommandsRequest]) (*connect.Response[v1.ListCommandsResponse], error)
}

